  filed: { label: 'Paid, filed', stamp: 'FILED', ink: 'blue' },
  needs_you: { label: 'Needs you', stamp: 'CHECK THIS', ink: 'red' },
  approved: { label: 'Approved', stamp: 'APPROVED', ink: 'blue' },
